INSERT OR IGNORE INTO products(id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,approved,stock,active,source_url,source_shop) SELECT 'TS0363','Medicube','PDRN Pink Tone Up Sun Cream SPF50+ PA++++','البشرة','واقي شمس','واقي شمس ميديكيوب PDRN Pink Tone Up بلمسة خوخية وردية لمظهر أكثر إشراقًا. يحمل SPF50+ PA++++ حسب العبوة، ويضم PDRN والنياسيناميد وحمض الهيالورونيك ضمن تركيبته.','{"imageType":"photo","collection":"k-beauty","koreanCare":true,"featuredOrder":100,"merchandisingPriority":0,"size":"50 ml","shade":"","intakeBatch":"2026-11-14","introductoryOffer":false,"contentVersion":"5.20.1","imageEditedWithAI":false,"nameAr":"واقي شمس ميديكيوب PDRN الوردي SPF50+ — 50 مل","tagline":"حماية يومية، ولمسة خوخية وردية.","productType":"sunscreen","benefits":["SPF50+ PA++++ حسب العبوة","لمسة خوخية وردية لتعديل مظهر اللون","قوام يومي خفيف"],"howToUse":"ضعيه بوفرة وبالتساوي كآخر خطوة صباحية قبل التعرض للشمس، وفق تعليمات العبوة. جددي التطبيق بانتظام وبعد التعرق أو السباحة، وتجنبي العينين.","variantNote":"إصدار PDRN Pink Tone Up بحجم 50 مل؛ يختلف عن Collagen Firming Sun Cream الموجود في المتجر.","notes":"اختبريه على منطقة صغيرة. توقفي عند التهيج واتبعي تعليمات العبوة.","en":{"name":"Medicube PDRN Pink Tone Up Sun Cream SPF50+ PA++++ · 50 ml","tagline":"Daily sun care with a peach-pink finish.","description":"A lightweight tone-up sunscreen with a peach-pink finish. The pack states SPF50+ PA++++; the formula features PDRN, niacinamide and hyaluronic acid.","benefits":["SPF50+ PA++++ as labelled","Peach-pink tone-up finish","Light daily texture"],"howToUse":"Apply generously and evenly as the final morning step before sun exposure, following your pack directions. Reapply regularly and after sweating or swimming. Avoid eyes.","variantNote":"50 ml PDRN Pink Tone Up version, distinct from Collagen Firming Sun Cream.","notes":"Patch test first. Stop if irritation occurs and follow the directions on your pack."}}',0,0,0,'/images/catalog/TS0363-ff2d643bfcab.webp',0,0,0,'owner-supplied:ScreenRecording_11-14-2026 19-14-36_1.mov#t=5','Owner video intake 2026-11-14' WHERE NOT EXISTS(SELECT 1 FROM products WHERE lower(trim(brand))=lower('Medicube') AND lower(trim(name))=lower('PDRN Pink Tone Up Sun Cream SPF50+ PA++++'));
