INSERT OR IGNORE INTO products(id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,approved,stock,active,source_url,source_shop) SELECT 'TS0364','Dr.Melaxin','TX-Astaxanthin Overnight Wrapping Mask','البشرة','ماسكات البشرة','ماسك ليلي يتكوّن على البشرة كغشاء قابل للإزالة، للعناية بالترطيب ومظهر الإشراقة وتفاوت اللون. تضم تركيبته الترانيكساميك والأستازانتين والنياسيناميد؛ وهو الأنبوب الأحمر بحجم 80 مل الظاهر في الفيديو.','{"imageType":"photo","collection":"k-beauty","koreanCare":true,"featuredOrder":100,"merchandisingPriority":0,"size":"80 ml","shade":"","intakeBatch":"2026-11-14","introductoryOffer":false,"contentVersion":"5.20.1","imageEditedWithAI":false,"nameAr":"ماسك دكتور ميلاكسين الليلي TX-Astaxanthin — 80 مل","tagline":"ختام هادئ لروتين المساء.","productType":"face-mask","benefits":["غشاء ختامي لروتين المساء","عناية بمظهر اللون غير المتجانس","ترطيب ومظهر أكثر نعومة"],"howToUse":"كآخر خطوة مساءً، وزعي طبقة متساوية بعيدًا عن العينين والشفاه والحاجبين وخط الشعر. اتركيها تجف تمامًا قبل النوم. صباحًا، أزيلي الغشاء برفق واشطفي البقايا بالماء الفاتر.","variantNote":"أنبوب الماسك الأحمر 80 مل. ظهور أداة التطبيق في الفيديو لا يؤكد أنها مشمولة مع المنتج.","notes":"اختبريه على منطقة صغيرة. توقفي عند التهيج واتبعي تعليمات العبوة. لا تنزعي الغشاء بقوة أو تضعيه على بشرة متهيجة.","en":{"name":"Dr.Melaxin TX-Astaxanthin Overnight Wrapping Mask · 80 ml","tagline":"A quiet finishing step for your evening.","description":"An overnight film-forming mask for hydration and the appearance of uneven tone and texture. Features tranexamic acid, astaxanthin and niacinamide in the pictured red 80 ml tube.","benefits":["An evening finishing film","Uneven-looking tone care","Hydrated, smoother-looking skin"],"howToUse":"As the final evening step, spread evenly, avoiding eyes, lips, brows and hairline. Allow to dry completely before sleeping. Gently peel away in the morning and rinse residue with lukewarm water.","variantNote":"Red 80 ml tube. The video does not confirm whether the pictured applicator is included.","notes":"Patch test first. Stop if irritation occurs and follow the directions on your pack. Never force peeling or apply to irritated skin."}}',0,0,0,'/images/catalog/TS0364-b6920e793dcb.webp',0,0,0,'owner-supplied:ScreenRecording_11-14-2026 19-14-36_1.mov#t=6','Owner video intake 2026-11-14' WHERE NOT EXISTS(SELECT 1 FROM products WHERE lower(trim(brand))=lower('Dr.Melaxin') AND lower(trim(name))=lower('TX-Astaxanthin Overnight Wrapping Mask'));
