INSERT OR IGNORE INTO products(id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,approved,stock,active,source_url,source_shop) SELECT 'TS0365','Dr.Melaxin','Peel Shot PS Glow Rice Toner','البشرة','التونر','تونر أرز مرطب من دكتور ميلاكسين لخطوة العناية بعد التنظيف. تحمل العبوة عبارة Rice Bran Water H + Ceramide، للعناية بالنعومة والرطوبة ومظهر الإشراقة. هذا التونر يختلف عن أمبولات تقشير الأرز.','{"imageType":"photo","collection":"k-beauty","koreanCare":true,"featuredOrder":100,"merchandisingPriority":0,"size":"200 ml","shade":"","intakeBatch":"2026-11-14","introductoryOffer":false,"contentVersion":"5.20.1","imageEditedWithAI":false,"nameAr":"تونر الأرز دكتور ميلاكسين Peel Shot Glow Rice — 200 مل","tagline":"لمسة الأرز لروتين ناعم ومشرق.","productType":"toner","benefits":["ترطيب بعد التنظيف","ماء نخالة الأرز والسيراميد حسب العبوة","لمظهر ناعم ومشرق"],"howToUse":"بعد التنظيف، ضعي كمية مناسبة على راحة اليد أو قطعة قطن، ووزعيها بلطف باتجاه نسيج البشرة بعيدًا عن العينين. أكملي بالمرطب، وبواقي الشمس صباحًا.","variantNote":"Peel Shot PS Glow Rice Toner بحجم 200 مل، بعبوة وغطاء ذهبي كما في الفيديو؛ ليس أمبول White Rice أو Black Rice.","notes":"اختبريه على منطقة صغيرة. توقفي عند التهيج واتبعي تعليمات العبوة.","en":{"name":"Dr.Melaxin Peel Shot PS Glow Rice Toner · 200 ml","tagline":"A rice-care moment for soft, radiant-looking skin.","description":"A moisturizing post-cleanse rice toner. The pictured pack reads Rice Bran Water H + Ceramide, for softness, moisture and radiance care. This is distinct from the rice exfoliating ampoules.","benefits":["Post-cleanse moisture care","Rice bran water and ceramide as labelled","Soft, radiant-looking skin"],"howToUse":"After cleansing, dispense onto your palm or a cotton pad. Gently smooth along skin texture, avoiding eyes. Follow with moisturizer and morning sunscreen.","variantNote":"Pictured 200 ml Peel Shot PS Glow Rice Toner with gold cap; not the White Rice or Black Rice ampoule.","notes":"Patch test first. Stop if irritation occurs and follow the directions on your pack."}}',0,0,0,'/images/catalog/TS0365-232093abc389.webp',0,0,0,'owner-supplied:ScreenRecording_11-14-2026 19-14-36_1.mov#t=7','Owner video intake 2026-11-14' WHERE NOT EXISTS(SELECT 1 FROM products WHERE lower(trim(brand))=lower('Dr.Melaxin') AND lower(trim(name))=lower('Peel Shot PS Glow Rice Toner'));
